    const input = [_][]const u8{
        " _ ", //
        " _|", //
        " _|", //
        "   ", //
    };
    try testing.expectEqualStrings("3", try convert(&buffer, &input));
}

test "Recognizes 4" {
    var buffer: [buffer_size]u8 = undefined;
    const input = [_][]const u8{
        "   ", //
        "|_|", //
        "  |", //
        "   ", //
    };
    try testing.expectEqualStrings("4", try convert(&buffer, &input));
}

test "Recognizes 5" {
    var buffer: [buffer_size]u8 = undefined;
    const input = [_][]const u8{
        " _ ", //
        "|_ ", //
        " _|", //
